from IQCommon.logger import user_log
DEFAULT_PORT = 8870
def handle_backtest_build(user_id=None, strategy_id=None, frequency=None, start_time=None, end_time=None, base_capital=None):
    if user_id is None or strategy_id is None or frequency is None or start_time is None or end_time is None or base_capital is None:
        return ({'code': '2', 'message': '参数错误'}, None, None)
    else:
        strategy = get_strategy(user_id, strategy_id)
        content = strategy['content']
        user_variables = strategy['user_variables']
        benchmark = strategy['benchmark']
        volume_limit = strategy['volume_limit']
        business_type = strategy['business_type']
        price_impact = strategy['price_impact']
        backtest_name = strategy['name']
        if get_docker_status(user_id) is False:
            return ({'code': '2', 'message': '容器未启动'}, None, None)
        else:
            mem_value = get_host_mem()
            if mem_value['error_no'] != 0:
                return ({'code': '2', 'message': mem_value['error_msg']}, None, None)
            try:
                recode = whitelist_filter(content)
                if recode['error_no'] != 0:
                    err_msg = ','.join(recode['error_list']) + '被禁止使用'
                    user_log.error(f'用户{user_id!s}回测创建失败，错误原因：{err_msg!s}')
                    return ({'code': '3', 'message': str(err_msg)}, None, None)
            except ImportError as e:
                return ({'code': '3', 'message': str(e.msg)}, None, None)
            except SyntaxError as e:
                return ({'code': '3', 'message': str(e.msg)}, None, None)
            strategy_dir = os.path.join(STRATEGY_DIR_PATH, user_id)
            strategy_file = strategy_id + '.dat'
            strategy_file_path = os.path.join(strategy_dir, strategy_file)
            backtest_id = str(uuid.uuid1())
            backtest_id_path = os.path.join(BACKTEST_DIR_PATH, backtest_id)
            strategy_path = os.path.join(backtest_id_path, 'user_strategy.py')
            accounts = dict()
            if business_type == 'rzrq':
                business_type = 'stock'
            accounts[business_type] = base_capital
            if frequency == 'minute':
                iqe_frequency = '1m'
            elif frequency == 'daily':
                iqe_frequency = '1d'
            elif frequency == 'tick':
                iqe_frequency = 'tick'
            else:
                return ({'code': '2', 'message': '参数错误'}, None, None)
            enable_profiler = 'false'
            enable_debug = 'false'
            backtest_type = '3'
            iqe_strategy = {'run_type': 'BACKTEST', 'frequency': iqe_frequency, 'start_date': start_time, 'end_date': end_time, 'accounts': accounts, 'path': strategy_path, 'backtest_id': backtest_id, 'benchmark': benchmark, 'business_type': business_type, 'user_variables': user_variables, 'volume_limit': volume_limit, 'safe': {'type': 'FILE'}}
            iqe_general = '"strategy": %s' % iqe_strategy
            backtest_path = BACKTEST_DIR_PATH
            so_error_path = os.path.join(BACKTEST_DIR_PATH, backtest_id, 'fly_so_error.log')
            user_code = f"\n# 用于打印so报错信息\nimport faulthandler\nfaulthandler.enable(open(\"{so_error_path!s}\",'a+'), all_threads=True)\nfrom IQEngine.main import run\nfrom IQEngine.config import parse_config\n\nconfig = {{\n{iqe_general!s},\n\"plugins\": {{\n    \"plugin_system_trade\": {{\n        \"enabled\": False,\n    }},\n    \"plugin_system_simulation\": {{\n        \"enabled\": True,\n        \"user_id\": \"{user_id!s}\",\n        \"account_sync_steps\": 10,\n    }},\n    \"plugin_system_log\": {{\n        \"backtest\": {{\n            \"backtest\": \"{backtest_path!s}\",\n            \"backtest_info\": \"{BACKTEST_INFO_FILENAME!s}\",\n            \"backtest_sys\": \"{BACKTEST_SYS_FILENAME!s}\",\n        }},\n        \"trade\": {{\n            \"trade_normal\": \"/home/fly/sim_backtest/result/\",\n            \"trade_info\": \"trade_norm.log\",\n            \"trade_sys\": \"trade_norm_sys.log\",\n        }},\n        \"enabled\": {'1'!s},\n        \"priority\": 2,\n    }},\n    \"plugin_fly_data_source\": {{\n        \"enabled\": {frequency != 'tick'!s},\n        \"priority\": 3,\n        \"config_path\": \"/home/fly/config/IQData_config.yml\"\n    }},\n    \"plugin_fly_data\": {{\n        \"enabled\": True,\n        \"price_impact\": {price_impact!s}\n    }},\n    \"plugin_system_debug\": {{\n        \"enabled\": {enable_debug == 'true'!s},\n        \"debug_port\": {DEFAULT_PORT!s},\n    }},\n    \"plugin_fly_api\": {{\n        \"enabled\": True,\n    }},\n}},\n}}\n\nconfig = parse_config(config)\nrun(config, user_variables={user_variables!s})\n"
            dir_path = os.path.join(BACKTEST_DIR_PATH, user_id, backtest_id)
            if not os.path.exists(dir_path):
                os.makedirs(dir_path)
                os.chmod(dir_path, 511)
            user_strategy_path = '%s/user_strategy.py' % dir_path
            with open(user_strategy_path, 'w') as file_user:
                file_user.write(content)
                os.chmod(user_strategy_path, 511)
            error = verify_user_py_code(user_strategy_path)
            if error is not None:
                if isinstance(error, CompileError):
                    return ({'code': '2', 'message': '编译错误：%s' % error.message}, None, None)
                elif isinstance(error, UnknownError):
                    return ({'code': '2', 'message': '未知错误：%s' % error.message}, None, None)
                return ({'code': '2', 'message': error.message}, None, None)
            else:
                user_code_path = '%s/user_code.py' % dir_path
                with open(user_code_path, 'w') as f:
                    f.write(user_code)
                    os.chmod(user_code_path, 511)
                strategy_path = os.path.join(STRATEGY_DIR_PATH, user_id, strategy_id + '.dat')
                backtest_path = os.path.join(BACKTEST_DIR_PATH, user_id, backtest_id)
                try:
                    shutil.copy(strategy_path, backtest_path)
                except FileExistsError as e:
                    return ({'code': '2', 'message': '策略文件缺失'}, None, None)
                time = datetime.datetime.now()
                total_days = len(get_trade_days(start_time, end_time))
                algorithm_period_return = '0'.ljust(22, ' ')
                max_drawdown = '0'.ljust(22, ' ')
                current_days = '0'.ljust(len(str(total_days)), ' ')
                info = save_backtest_info_csv_without_pd(user_id, backtest_id, strategy_id, base_capital, frequency, business_type, backtest_type, start_time, end_time, time, algorithm_period_return, max_drawdown, current_days, backtest_name, total_days)
                if not info:
                    return ({'code': '2', 'message': '保存回测信息失败'}, None, None)
                else:
                    cell_code = f'docker exec -d jupyter-{user_id!s} su - fly -c "/usr/bin/python3 /home/fly/backtest/{backtest_id!s}/user_code.py" &'
                    return ({'code': '1', 'message': ''}, cell_code, backtest_id)
